<?php
require __DIR__.'/includes/bootstrap.php';
$page=$_GET['page']??(user()?'dashboard':'home');
$public=['home','login','register'];
if(!in_array($page,$public,true)) require_login();
$role=user()['role']??'';
$allowed=[
 'dashboard'=>['Student','Instructor','Administrator'],
 'rooms'=>['Student','Instructor','Administrator'],'guests'=>['Student','Instructor','Administrator'],
 'reservations'=>['Student','Instructor','Administrator'],'frontdesk'=>['Student','Instructor','Administrator'],
 'housekeeping'=>['Student','Instructor','Administrator'],'billing'=>['Student','Instructor','Administrator'],
 'scenarios'=>['Student','Instructor','Administrator'],'assessments'=>['Student','Instructor','Administrator'],
 'users'=>['Instructor','Administrator'],'reports'=>['Instructor','Administrator'],'logs'=>['Administrator'],
 'settings'=>['Administrator'],'profile'=>['Student','Instructor','Administrator']
];
if(isset($allowed[$page])&&!in_array($role,$allowed[$page],true)){http_response_code(403);exit('You do not have permission to access this page.');}
if($page==='login'&&user())redirect('index.php');
if($page==='register'&&user())redirect('index.php');
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 $action=$_POST['action']??'';
 try {
  if($action==='login'){
   $s=$pdo->prepare('SELECT * FROM users WHERE email=? AND status="Active"');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();
   if(!$u||!password_verify($_POST['password']??'',$u['password']))throw new Exception('Invalid email or password.');
   session_regenerate_id(true);$_SESSION['user']=['user_id'=>$u['user_id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']];
   log_activity($pdo,'Logged in');redirect('index.php');
  }
  if($action==='register'){
   $name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';
   if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)throw new Exception('Enter a name, valid email, and password of at least 8 characters.');
   $s=$pdo->prepare('INSERT INTO users(full_name,email,password,role,department,year_level) VALUES(?,?,?,"Student",?,?)');
   $s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),trim($_POST['department']??'Hospitality Management'),trim($_POST['year_level']??'')]);
   flash('Account created. You can now sign in.');redirect('index.php?page=login');
  }
  if($action==='logout'){log_activity($pdo,'Logged out');session_destroy();redirect('index.php?page=login');}
  if($action==='save_room'){
   require_role(['Administrator']);$id=(int)($_POST['room_id']??0);
   $data=[trim($_POST['room_number']),trim($_POST['room_type']),(int)$_POST['floor'],(float)$_POST['rate'],(int)$_POST['max_occupancy'],$_POST['housekeeping_status'],$_POST['occupancy_status']];
   if($id){$q=$pdo->prepare('UPDATE room SET room_number=?,room_type=?,floor=?,rate=?,max_occupancy=?,housekeeping_status=?,occupancy_status=? WHERE room_id=?');$q->execute([...$data,$id]);}
   else{$q=$pdo->prepare('INSERT INTO room(room_number,room_type,floor,rate,max_occupancy,housekeeping_status,occupancy_status) VALUES(?,?,?,?,?,?,?)');$q->execute($data);}
   log_activity($pdo,'Saved room '.$data[0]);flash('Room saved.');redirect('index.php?page=rooms');
  }
  if($action==='delete_room'){require_role(['Administrator']);$q=$pdo->prepare('DELETE FROM room WHERE room_id=?');$q->execute([(int)$_POST['id']]);flash('Room deleted.');redirect('index.php?page=rooms');}
  if($action==='save_guest'){
   require_login();$q=$pdo->prepare('INSERT INTO guest(full_name,email,phone,address,id_type,preferences) VALUES(?,?,?,?,?,?)');
   $q->execute([trim($_POST['full_name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['id_type']),trim($_POST['preferences'])]);
   log_activity($pdo,'Registered guest '.trim($_POST['full_name']));flash('Guest saved.');redirect('index.php?page=guests');
  }
  if($action==='save_reservation'){
   require_login();$guest=(int)$_POST['guest_id'];$room=(int)$_POST['room_id'];$in=$_POST['check_in_date'];$out=$_POST['check_out_date'];$pax=(int)$_POST['pax'];$n=nights($in,$out);
   if($n<1||$pax<1)throw new Exception('Check-out must be after check-in and guest count must be positive.');
   $r=$pdo->prepare('SELECT rate,max_occupancy FROM room WHERE room_id=?');$r->execute([$room]);$roomData=$r->fetch();
   if(!$roomData||$pax>(int)$roomData['max_occupancy']||!room_is_free($pdo,$room,$in,$out))throw new Exception('Room is unavailable, invalid, or over capacity.');
   $q=$pdo->prepare('INSERT INTO reservation(guest_id,room_id,user_id,booking_type,check_in_date,check_out_date,number_of_nights,pax,reservation_status) VALUES(?,?,?,?,?,?,?,?,?)');
   $q->execute([$guest,$room,user()['user_id'],$_POST['booking_type'],$in,$out,$n,$pax,'Confirmed']);
   $rid=(int)$pdo->lastInsertId();$subtotal=(float)$roomData['rate']*$n;
   $pdo->prepare('INSERT INTO folio(reservation_id,subtotal,tax_rate,tax_amount,grand_total,payment_status) VALUES(?,?,?,?,?,"Unpaid")')->execute([$rid,$subtotal,0,$subtotal*0,$subtotal]);
   log_activity($pdo,'Created reservation #'.$rid);flash('Reservation confirmed and folio created.');redirect('index.php?page=reservations');
  }
  if($action==='reservation_status'){
   require_login();$id=(int)$_POST['id'];$status=$_POST['status'];
   if(!in_array($status,['Cancelled','Checked-in','Checked-out'],true))throw new Exception('Invalid status.');
   $pdo->beginTransaction();$q=$pdo->prepare('SELECT room_id FROM reservation WHERE reservation_id=?');$q->execute([$id]);$room=$q->fetchColumn();
   $pdo->prepare('UPDATE reservation SET reservation_status=? WHERE reservation_id=?')->execute([$status,$id]);
   if($status==='Checked-in')$pdo->prepare('UPDATE room SET occupancy_status="Occupied" WHERE room_id=?')->execute([$room]);
   if($status==='Checked-out')$pdo->prepare('UPDATE room SET occupancy_status="Available",housekeeping_status="Dirty" WHERE room_id=?')->execute([$room]);
   if($status==='Cancelled')$pdo->prepare('UPDATE room SET occupancy_status="Available" WHERE room_id=?')->execute([$room]);
   $pdo->commit();log_activity($pdo,'Changed reservation #'.$id.' to '.$status);flash('Reservation updated.');redirect('index.php?page=reservations');
  }
  if($action==='room_status'){require_login();$pdo->prepare('UPDATE room SET housekeeping_status=?,occupancy_status=? WHERE room_id=?')->execute([$_POST['housekeeping_status'],$_POST['occupancy_status'],(int)$_POST['id']]);flash('Room status updated.');redirect('index.php?page=housekeeping');}
  if($action==='save_scenario'){require_role(['Instructor','Administrator']);$pdo->prepare('INSERT INTO scenario(title,description,difficulty,learning_objectives,instructions,target_points) VALUES(?,?,?,?,?,?)')->execute([trim($_POST['title']),trim($_POST['description']),$_POST['difficulty'],trim($_POST['learning_objectives']),trim($_POST['instructions']),(int)$_POST['target_points']]);flash('Scenario created.');redirect('index.php?page=scenarios');}
  if($action==='submit_assessment'){require_role(['Student']);$pdo->prepare('INSERT INTO student_assessment(user_id,scenario_id,submission_status,student_notes) VALUES(?,?,"Submitted",?)')->execute([user()['user_id'],(int)$_POST['scenario_id'],trim($_POST['student_notes'])]);flash('Activity submitted for instructor review.');redirect('index.php?page=assessments');}
  if($action==='grade_assessment'){require_role(['Instructor','Administrator']);$pdo->prepare('UPDATE student_assessment SET score=?,instructor_feedback=?,submission_status="Reviewed",completed_at=NOW() WHERE assessment_id=?')->execute([(float)$_POST['score'],trim($_POST['feedback']),(int)$_POST['id']]);flash('Assessment graded.');redirect('index.php?page=assessments');}
  if($action==='save_user'){require_role(['Administrator']);$id=(int)($_POST['user_id']??0);$name=trim($_POST['full_name']);$email=trim($_POST['email']);$role=$_POST['role'];if(!in_array($role,['Student','Instructor','Administrator']))throw new Exception('Invalid role.');if($id){$pdo->prepare('UPDATE users SET full_name=?,email=?,role=?,status=? WHERE user_id=?')->execute([$name,$email,$role,$_POST['status'],$id]);}else{$pw=password_hash($_POST['password']?:bin2hex(random_bytes(6)),PASSWORD_DEFAULT);$pdo->prepare('INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,?)')->execute([$name,$email,$pw,$role]);}flash('User saved.');redirect('index.php?page=users');}
  if($action==='save_folio'){require_login();$id=(int)$_POST['folio_id'];$discount=max(0,(float)$_POST['discount_amount']);$taxRate=max(0,(float)$_POST['tax_rate']);$subtotal=(float)$_POST['subtotal'];$extra=max(0,(float)$_POST['additional_charges']);$taxable=max(0,$subtotal-$discount+$extra);$tax=$taxable*$taxRate/100;$total=$taxable+$tax;$pdo->prepare('UPDATE folio SET subtotal=?,discount_amount=?,tax_rate=?,tax_amount=?,grand_total=?,payment_status=? WHERE folio_id=?')->execute([$subtotal,$discount,$taxRate,$tax,$total,$_POST['payment_status'],$id]);if($extra>0)$pdo->prepare('INSERT INTO folio_item(folio_id,description,category,amount) VALUES(?,?,?,?)')->execute([$id,'Additional charges','Other',$extra]);flash('Folio updated. Simulation only; no real payment was processed.');redirect('index.php?page=billing');}
 } catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');redirect('index.php?page='.($_GET['page']??'dashboard'));}
}
