<?php elseif($page==='reservations'): ?>
<section class="card"><h3>Create reservation</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_reservation"><select name="guest_id" required><option value="">Select guest</option><?php foreach($pdo->query('SELECT guest_id,full_name FROM guest ORDER BY full_name') as $g): ?><option value="<?=$g['guest_id']?>"><?=e($g['full_name'])?></option><?php endforeach; ?></select><select name="room_id" required><option value="">Select room</option><?php foreach($pdo->query('SELECT room_id,room_number,room_type,rate FROM room WHERE occupancy_status<>"Maintenance" ORDER BY room_number') as $r): ?><option value="<?=$r['room_id']?>"><?=e($r['room_number'].' · '.$r['room_type'].' · '.money($r['rate']))?></option><?php endforeach; ?></select><select name="booking_type"><option>Advance</option><option>Walk-in</option></select><label>Check-in <input type="date" name="check_in_date" required></label><label>Check-out <input type="date" name="check_out_date" required></label><input type="number" name="pax" min="1" value="1" placeholder="Number of guests" required><button class="btn btn-gold">Confirm reservation</button></form><small class="muted">Room date overlaps and room capacity are validated before confirmation.</small></section><section class="card"><div class="section-head"><h3>Reservation records</h3><input class="search" placeholder="Search..." oninput="filterRows(this,'res-table')"></div><div class="table-wrap"><table id="res-table"><thead><tr><th>Ref.</th><th>Guest</th><th>Room</th><th>Stay</th><th>Nights</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php $rs=$pdo->query('SELECT r.*,g.full_name,ro.room_number FROM reservation r JOIN guest g ON g.guest_id=r.guest_id JOIN room ro ON ro.room_id=r.room_id ORDER BY r.reservation_id DESC');foreach($rs as $r): ?><tr><td>#<?=$r['reservation_id']?></td><td><?=e($r['full_name'])?></td><td><?=e($r['room_number'])?></td><td><?=e($r['check_in_date'])?> – <?=e($r['check_out_date'])?></td><td><?=$r['number_of_nights']?></td><td><span class="status"><?=e($r['reservation_status'])?></span></td><td><div class="actions"><?php foreach(['Checked-in','Checked-out','Cancelled'] as $st): if(($st==='Checked-in'&&$r['reservation_status']==='Confirmed')||($st==='Checked-out'&&$r['reservation_status']==='Checked-in')||($st==='Cancelled'&&in_array($r['reservation_status'],['Pending','Confirmed']))): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reservation_status"><input type="hidden" name="id" value="<?=$r['reservation_id']?>"><input type="hidden" name="status" value="<?=$st?>"><button class="btn-small"><?=$st?></button></form><?php endif;endforeach;?></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif($page==='frontdesk'): ?><section class="card"><span class="eyebrow">FRONT DESK WORKSPACE</span><h3>Arrivals, in-house guests and departures</h3><p>Use the Reservations module to verify a booking and perform check-in or check-out. Room occupancy and housekeeping statuses synchronize automatically.</p><a class="btn btn-gold" href="index.php?page=reservations">Open reservations</a></section>
<?php elseif($page==='billing'): ?><section class="card"><h3>Guest folios</h3><div class="table-wrap"><table><thead><tr><th>Folio</th><th>Reservation</th><th>Guest</th><th>Subtotal</th><th>Tax</th><th>Total</th><th>Payment status</th><th>Update</th></tr></thead><tbody><?php $fs=$pdo->query('SELECT f.*,r.reservation_id,g.full_name FROM folio f JOIN reservation r ON r.reservation_id=f.reservation_id JOIN guest g ON g.guest_id=r.guest_id ORDER BY f.folio_id DESC');foreach($fs as $f): ?><tr><td>#<?=$f['folio_id']?></td><td>#<?=$f['reservation_id']?></td><td><?=e($f['full_name'])?></td><td><?=money($f['subtotal'])?></td><td><?=money($f['tax_amount'])?></td><td><b><?=money($f['grand_total'])?></b></td><td><?=e($f['payment_status'])?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="save_folio"><input type="hidden" name="folio_id" value="<?=$f['folio_id']?>"><input type="hidden" name="subtotal" value="<?=$f['subtotal']?>"><input type="number" name="discount_amount" step=".01" min="0" placeholder="Discount" required><input type="number" name="tax_rate" step=".01" min="0" value="<?=$f['tax_rate']?>" title="Tax %"><input type="number" name="additional_charges" step=".01" min="0" value="0" placeholder="Extra"><select name="payment_status"><option>Unpaid</option><option>Paid (Simulation)</option><option>Partially Paid (Simulation)</option></select><button class="btn-small">Save</button><button type="button" class="btn-small" onclick="window.print()">Print</button></form></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">All payment statuses are simulated. No real payment is processed.</p></section>
<?php elseif($page==='scenarios'): ?><section class="card"><?php if(in_array(user()['role'],['Instructor','Administrator'])): ?><h3>Create learning scenario</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_scenario"><input name="title" placeholder="Scenario title" required><select name="difficulty"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select><input type="number" name="target_points" value="100" min="1"><input name="description" placeholder="Description" required><input name="learning_objectives" placeholder="Learning objectives"><textarea name="instructions" placeholder="Instructions"></textarea><button class="btn btn-gold">Create scenario</button></form><?php endif; ?><h3>Available learning scenarios</h3><div class="scenario-grid"><?php foreach($pdo->query('SELECT * FROM scenario ORDER BY scenario_id DESC') as $s): ?><article class="scenario"><span class="status"><?=e($s['difficulty'])?></span><h4><?=e($s['title'])?></h4><p><?=e($s['description'])?></p><small><?=e($s['learning_objectives'])?></small><?php if(user()['role']==='Student'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="submit_assessment"><input type="hidden" name="scenario_id" value="<?=$s['scenario_id']?>"><textarea name="student_notes" placeholder="Describe your completed activity..." required></textarea><button class="btn btn-gold">Submit activity</button></form><?php endif; ?></article><?php endforeach; ?></div></section>
<?php elseif($page==='assessments'): ?><section class="card"><h3><?=user()['role']==='Student'?'My submissions':'Student submissions for review'?></h3><div class="table-wrap"><table><thead><tr><th>Student</th><th>Scenario</th><th>Submitted</th><th>Status</th><th>Score</th><th>Feedback / Review</th></tr></thead><tbody><?php $sql='SELECT a.*,u.full_name,s.title FROM student_assessment a JOIN users u ON u.user_id=a.user_id JOIN scenario s ON s.scenario_id=a.scenario_id';if(user()['role']==='Student'){$sql.=' WHERE a.user_id='.(int)user()['user_id'];}$sql.=' ORDER BY a.assessment_id DESC';foreach($pdo->query($sql) as $a): ?><tr><td><?=e($a['full_name'])?></td><td><?=e($a['title'])?></td><td><?=e($a['created_at'])?></td><td><?=e($a['submission_status'])?></td><td><?=e($a['score']??'—')?></td><td><?php if(in_array(user()['role'],['Instructor','Administrator'])&&$a['submission_status']==='Submitted'): ?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="grade_assessment"><input type="hidden" name="id" value="<?=$a['assessment_id']?>"><input type="number" name="score" min="0" max="100" step=".5" placeholder="Score" required><input name="feedback" placeholder="Feedback"><button class="btn-small">Grade</button></form><?php else: ?><?=e($a['instructor_feedback']??'Awaiting review')?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif($page==='users'): ?><section class="card"><h3>Create user account</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_user"><input name="full_name" placeholder="Full name" required><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Temporary password (optional)"><select name="role"><option>Student</option><option>Instructor</option><option>Administrator</option></select><button class="btn btn-gold">Create user</button></form><h3>Accounts</h3><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($pdo->query('SELECT * FROM users ORDER BY user_id DESC') as $u): ?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="save_user"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><input name="full_name" value="<?=e($u['full_name'])?>" required><input type="email" name="email" value="<?=e($u['email'])?>" required><select name="role"><option <?= $u['role']==='Student'?'selected':'' ?>>Student</option><option <?= $u['role']==='Instructor'?'selected':'' ?>>Instructor</option><option <?= $u['role']==='Administrator'?'selected':'' ?>>Administrator</option></select><select name="status"><option>Active</option><option>Inactive</option></select><button class="btn-small">Update</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif($page==='reports'): ?><div class="stats-grid"><?php foreach($counts as $k=>$v): ?><div class="stat-card"><span><?=ucfirst($k)?></span><strong><?=$v?></strong><small>Database total</small></div><?php endforeach; ?></div><section class="card"><h3>Reservation report</h3><div class="table-wrap"><table><thead><tr><th>Status</th><th>Reservations</th></tr></thead><tbody><?php foreach($pdo->query('SELECT reservation_status,COUNT(*) total FROM reservation GROUP BY reservation_status') as $r): ?><tr><td><?=e($r['reservation_status'])?></td><td><?=$r['total']?></td></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-outline" onclick="window.print()">Print report</button></section>
<?php elseif($page==='logs'): ?><section class="card"><h3>System activity logs</h3><div class="table-wrap"><table><thead><tr><th>User</th><th>Action</th><th>Timestamp</th></tr></thead><tbody><?php foreach($pdo->query('SELECT a.*,u.full_name FROM activity_log a JOIN users u ON u.user_id=a.user_id ORDER BY a.log_id DESC LIMIT 200') as $l): ?><tr><td><?=e($l['full_name'])?></td><td><?=e($l['action'])?></td><td><?=e($l['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif($page==='settings'): ?><section class="card"><h3>System configuration</h3><p>System: C.I.H.R.M.</p><p>Environment: Educational simulation only</p><p>Payments: No real-money processing</p><p>Tax and discount values can be configured per folio in the Billing module.</p></section>
<?php elseif($page==='profile'): ?><section class="card"><h3>Account profile</h3><p><b>Name:</b> <?=e(user()['full_name'])?></p><p><b>Email:</b> <?=e(user()['email'])?></p><p><b>Role:</b> <?=e(user()['role'])?></p><p><b>User ID:</b> <?=e(user()['user_id'])?></p></section>
<?php endif; endif; ?>
<?php if(user()): ?></main><?php else: ?></main><?php endif; ?><script src="assets/js/app.js"></script></body></html>
